from pathlib import Path
import json,re
root=Path('challenge')
catalog=json.loads((root/'catalog.json').read_text('utf8'))['challenges']
data=[]
def add(title, mechanism, steps, result, limitations='', pages='', category=None):
 matches=[x for x in catalog if (x['title']==title or x['directory'].split('/')[-1]==title) and x['category'] in ['android','iot','车联网'] and (not category or x['category']==category)]
 assert len(matches)==1,(title,len(matches))
 x=matches[0]; p=root/x['directory']; sources=[f for f in (p/'writeups').rglob('*') if f.is_file() and f.suffix.lower() in ['.md','.txt','.py','.js','.sh','.pdf']]
 # HTML text is preferred; large official PDF duplicates are secondary if a specific README exists.
 evidence=[f.relative_to(p).as_posix() for f in sources]
 text=f"# {title} — AI 易理解版 Writeup\n\n> 比赛：{x['event_title']}｜目录分类：{x['category']}｜分析日期：2026-11-06\n> 依据本地资料改写；未运行题目程序、solver 或远程利用。文中输出均为原文记录，不能当作本次复现结果。\n\n## 目标与核心机制\n\n{mechanism}\n\n## 材料与证据\n\n"
 for f in evidence: text+=f'- [{f}](<{f}>)\n'
 if pages:text+=f'\n本题在合集中的定位：{pages}。仅使用本题章节，不能用其他章节的 flag 作为结果。\n'
 text+='\n## 推导与解题步骤\n\n'
 for i,s in enumerate(steps.split('||'),1):text+=f'{i}. {s}\n\n'
 text+=f'## 结果与验证\n\n{result}\n\n## 复现边界与易错点\n\n{limitations or "原文所列路径、地址和工具行为对应比赛附件版本。先核对本地附件及参数，再进行复现；本文不承诺历史远程服务仍可用。"}\n\n附件登记状态：{x["attachment_state"]}。文件清单与来源见 [本题 README](README.md)；关键原始代码保留在上述证据文件中。\n'
 (p/'AI_WRITEUP.md').write_text(text,'utf8')
 data.append({'directory':x['directory'],'mechanism':mechanism,'evidence':evidence,'limitations':limitations or '静态资料改写；未运行复现。','status':'rewritten_with_limitations' if limitations else 'rewritten_static'})

add('AGL 1','目标是从 Automotive Grade Linux 镜像找出第一个 flag。线索来自串口登录画面的 5900/tcp 提示；启动脚本的 `-vnc :0` 表明 GUI 已通过 VNC 导出。flag 位于仪表盘图标本身，不需要破解系统口令。','检查 run.sh 中内核、raw 磁盘及 `-vnc :0` 参数；确认图形输出映射到本机5900端口。||在隔离的比赛镜像环境启动后，以 VNC 客户端查看桌面。Dashboard 图标下方直接包含文字，应放大读取而不是只搜索终端日志。||离线交叉验证：从镜像取出 `/usr/share/icons/hicolor/scalable/dashboard.svg`，检查图标文字；这与VNC看到的结果应一致。','官方第21页记录 `FLAG{W3lc0m3_t0_AGL!}`。验证标准是 SVG 内容与 GUI 展示一致。','原文提到镜像允许 root 空密码登录，这是本题镜像的配置，不能推广到任意 AGL。挂载分析宜使用只读副本。', '官方PDF第19—21页')
add('AGL 2','目标是恢复同一AGL镜像里的第二个flag。Camera页面只是线索展示，实际信息在JPEG的EXIF User Comment字段中，以Base64编码。','在Camera画面发现细小提示；GUI若旋转，可按第22页将weston.ini的`transform=rotate-90`改为rotate-0，仅为方便观察。||从镜像提取 `/usr/share/applications/data/still-image.jpg`。官方分区起点为2048扇区，扇区512字节，因此文件系统偏移是1048576；也可用7-Zip读取镜像。||放大图片得到“提取图片并分析”的提示，读取EXIF User Comment，将其中字符串Base64解码。','官方第25页给出 `FLAG{EXIF_c4n_h1d3_4nyth1ng}`。解码结果应包含flag2标识，不能把图中可见提示当flag。','磁盘偏移属于该附件版本；不要对所有raw镜像硬套1048576。EXIF比像素内容更关键。','官方PDF第22—25页')
add('AGL 3','目标是从AGL媒体资源恢复第三个flag。播放器中有音频，但QEMU默认启动未转发声音；提示藏在MP3末尾的人声及NATO字母拼读中。','查看Launcher的Media Player并定位`/media`中的MP3；文件名与Eine kleine Nachtmusik相关。||离线提取音频并完整播放，重点听结尾。界面无声只能说明音频未重定向，不能推出文件没有隐藏内容。||将结尾语音IMPERIAL OPERA与后续India、Mike、Papa等拼读互相校对，空格按明确的underscore提示转下划线。','由官方第28页文本得到 `FLAG{IMPERIAL_OPERA}`。两段语音给出的字符应一致。','本次未播放附件音频，结果来自官方逐字转录。无需把整段音乐进行频谱隐写分析。','官方PDF第26—28页')
add('AGL 4','目标是拼接分散在三个非主分区的flag片段。`/root/.hint.txt`提示可疑分区；各分区文件系统不同，单次strings或只看根分区会遗漏。','读取隐藏提示并保留NUL字节的存在，使用十六进制查看可避免普通strings漏掉提示。||枚举raw镜像分区。官方1.img为ext2，含flag4-part1.gif；2.img为SquashFS，含flag4-part2.zip，其内有文本片段。||3.img为F2FS，需要支持F2FS的读取工具或只读挂载，提取flag4-part3.zip。||按part1/3、part2/3、part3/3顺序拼接，不按文件枚举顺序猜测。','官方片段分别是 `FLAG{y0u_g0tta_b3`、`_susp1c10us_0f_un`、`us3d_p4rt1t10ns!}`；合并为 `FLAG{y0u_g0tta_b3_susp1c10us_0f_unus3d_p4rt1t10ns!}`。','片段来自PDF截图，应以原始GIF/文本复核易混淆的0/O与1/l；本次没有实际挂载镜像。','官方PDF第29—32页')
add('AGL 5','目标是读取KUKSA Data Broker中的41个字符。VSS JSON仅定义信号名称，值由启动服务动态写入，因此grep配置文件无法直接拿到完整flag。','读`/usr/share/vss/vss.json`，定位`Vehicle.ctf.flag5.c1`至c41及hint；hint指向`/usr/sbin/agl-vss-helper.py`。||从helper取得CA路径`/etc/kuksa-val/CA.pem`与token路径`/etc/xdg/AGL/agl-vss-helper/agl-vss-helper.token`，按官方示例连接`grpcs://127.0.0.1:55555`。||依次执行`getValue Vehicle.ctf.flag5.cN`，以数值N排序拼接1—41字符；不要使用字符串字典序。||静态备选：沿agl-setup.service→/usr/bin/agl-setup→/usr/lib/libaglsetup.so，恢复其用全零AES-256-ECB密钥解密的setValue命令。','官方第39页展示 `FLAG{valu3s_l1ve_1ns1d3_d4t4br0k3r}`。应检查41个槽位的实际返回与长度字段，不凭flag外观判成功。','运行中的值与schema定义分离；截图显示的flag字符可能与槽位总数不同，需保留完整值和服务返回作核对，不自行补字符。','官方PDF第33—40页')
add('VIN Hunter','目标是通过CAN上的UDS读取VIN数据标识符F190，题目把flag放在该DID中。关键是先发现请求/响应CAN ID，再通过ISO-TP承载UDS。','按题目canproxy连接到隔离vcan0环境；区分CAN帧、ISO-TP重组和UDS负载。||使用caringcaribou的UDS发现流程确定`TX=0x7E0`、`RX=0x7E8`。||对该ID对读取DID `0xF190`，正响应为`62 F1 90`后接数据。官方dump_dids直接打印的是DID值，不能再错误地裁掉三字节。||将十六进制`666c61677b76316e5f723361645f737563633373737d`解为ASCII。','官方记录 `flag{v1n_r3ad_succ3ss}`。检查响应ID及DID一致，防止读取其他ECU广播。',pages='官方PDF第5—7页')
add('Seed-Key Leak','目标是逆向dealer_unlock.pyc中的UDS SecurityAccess算法，通过0x27解锁后读取DID1337。核心是32位旋转、加法与异或；这不是暴力猜测seed。','反编译dealer_unlock.pyc并定位derive_key，保留每一步32位截断。||算法：`x=seed^0xA5C31F27; x=rol32(x,3); x=(x+0x1F1F0101)&0xffffffff; x^=0xDEADBEEF; key=ror32(x,1)`。||对7E0/7E8发送`10 03`进入扩展会话，再发送`27 01`；从`67 01`之后读取大端seed。||把计算结果编码为4字节大端，发送`27 02 <key>`，确认正响应后发送`22 13 37`，从`62 13 37`后解码flag。','验证至少包括扩展会话成功、SecurityAccess正响应和目标DID正响应；官方这段文本没有给出可独立核实的最终flag，不能挪用前题VIN flag。','原文PDF复制出的代码含缩进/反斜线排版问题，复现时应重建语法。种子来自当前会话，不应硬编码历史seed。','官方PDF第8—10页')
add('Gateway Gremlins','目标是串联遗留Web漏洞和CAN鉴权。Web链泄露算法，CAN nonce使密钥具有时效；仅拿到配置不等于完成解锁。','从robots.txt发现`/legacy/`。旧登录使用XML/XPath鉴权，经XPath注入进入diagnostic upload；此处不是SQL数据库注入。||上传含外部实体的XML读取`/app/config.json`，再按.bak提示读取`/app/config.json.bak`，备份里才包含完整密钥逻辑。||监听CAN ID0x555，将前4字节按大端解析为nonce。进入`10 03`会话，发送`27 05`取得seed。||计算`key=(rol32(seed ^ 0x5A17C0DE ^ nonce,7)+0x27110027)&0xffffffff`；以4字节大端发送`27 06`。nonce滚动时重新获取并重试，必要时重取当前seed。||解锁成功后读取`22 F1 A0`，剥离`62 F1 A0`响应头再解码。','每个阶段的证据依次是登录会话、配置备份中的算法、当前nonce、67 06正响应以及F1A0数据；PDF未在本题代码中列最终flag。','端点及常量仅适用于比赛环境。必须保持nonce与提交时刻一致；原文省略了通用UDS收发函数，可参考相邻Seed-Key Leak的结构。','官方PDF第11—18页')
add('I Saw Our Time Pass','目标是从CAN日志中重组ISO-TP ZIP，并从协议控制字段提取四层压缩包密码。负载中有大量假flag，真正内容在0x702的四重ZIP里。','按CAN ID及ISO-TP会话重组First Frame和Consecutive Frame，保留长度与序号，剔除PCI字段及末尾填充；从0x702找出四层嵌套ZIP。||密码1：读取0x708 Flow Control的Block Size，按数值转ASCII，得到`FL0W_C0N7R0L_C4RR135_M34N1N6`。||密码2：读取0x709的STmin原始字段值转ASCII，得到`53P4R4710N_71M3_15_4_CLU3`。||密码3：读取0x702各First Frame声明长度，减256后转ASCII，得到`F1R57_FR4M3_KN0W5_M0R3`。||密码4：收集0x703每段最后一个Consecutive Frame序号，每个序号是一个4位nibble，按顺序两两合成字节，得到`UD5_0V3R_1507P_H45_53CR375`。||用四个密码逐层解包；密码提示文本不是flag，应读最终flag.txt。','官方第50页给出 `FLAG{C4N_BU5_WH15P3R3R_W45_H3R3}`。验证ZIP结构/CRC、四层解包及最终文本，而非只搜索任意flag字符串。','CAN ID在幻灯片中按十六进制书写；Block Size示例输出则是十进制。不能混用打印进制。','官方PDF第42—50页')
add('RAMN ECU D','目标是通过UDS 0x29证书认证读取DID4E44。给定证书过期但验证逻辑正确；漏洞在嵌入的两个RSA根证书模数共用素因子，可以恢复根CA私钥并重签有效证书。','从ECUD.hex/固件中定位20个信任根：11个RSA-2048及9个ECDSA P-256。先筛选RSA模数，避免把椭圆曲线点当整数模数。||对RSA模数两两计算gcd。若1<p<min(n1,n2)，则p为共享素数；分别求q=n/p及私钥指数d=e^-1 mod φ(n)。||官方命中根索引4和13，共享1024位素因子。用恢复出的受信CA密钥，为已有客户端私钥重新签发有效期正确的证书。||以新证书及对应客户端私钥完成0x29认证，再读取0x4E44；只改证书日期会破坏签名，因此必须重新签发。','官方第116页记录 `FLAG{G00D_1MPL_P00R_K3Y_G3N}`。离线应校验重签证书链，在线需确认认证及DID读取均成功。','完整认证报文实现仅以外部gist链接给出，本文没有下载或执行它；本地PDF提供算法与成功日志，不能据此宣称已完成服务复现。','官方PDF第112—116页')
add('Parking Lot Whisper','目标是识别Falcon X1遥控器的中心频率、调制方式和最短符号周期。采样为433.92MHz中心、2Msps、复数float32小端，文件交替存I/Q。','将float32数组偶数项与奇数项组为`I+1j*Q`；FFT定位433.920、433.960、433.840MHz三个信号。||选取433.920MHz约80ms且每组三次重发的长帧，与按钮发射行为匹配。||计算幅度包络并平滑，按高低电平阈值测run长度。500us和1000us脉宽说明基本chip为500us，不能把最长脉宽当周期。||按题目要求用Hz、OOK、us格式输出。','原文记录 `flag{433920000_OOK_500}`。OOK是载波开关调制，本题判题要求OOK而不是更宽泛的ASK。',pages='kn1cht合集 Keyfob / Parking Lot Whispter（原文标题拼写）')
add('Read the simple fob','目标是恢复Manchester帧中同步字D5后的3字节Device ID，输入与Parking Lot Whisper相同。','按433.920MHz、2Msps、500us chip提取OOK电平；每chip约1000个采样点，在内部采样避免边缘噪声。||按`01→0,10→1`将两个chip还原一个bit；出现00或11时应修正帧边界或相位，而不是跳过错误。||按MSB-first每8bit成字节，以`AA AA D5`作同步校验；多次重发应得到相同`AA AA D5 7A 21 CC 20 01 37 5A`。||取D5后的7A 21 CC，大写十六进制无0x。','原文结果 `flag{7A21CC}`。同步字、三次重发一致性和字段长度是三个独立检查点。',pages='kn1cht合集 Keyfob / Read the simple fob')
add('Next Counter','目标是预测另一Falcon X1设备下一次Unlock帧。重复发射不代表计数器每帧递增，计数器按按钮操作递增。','用相同OOK/Manchester参数解capture_c3.bin。15帧分为每组三次重发，共5次操作。||去重后帧为`AA AA D5 9C 4E 2B 20 01 NN 5A`，NN依次37、38、39、3A、3B；两字节计数器是大端0137至013B。||保持前导、设备ID、命令20和尾字节5A不变，只把计数器增至013C。','原文记录 `flag{AAAAD59C4E2B20013C5A}`。先重建全部已观察帧再外推，可避免把固定尾字节当校验或错误增加重发计数。',pages='kn1cht合集 Keyfob / Next Counter')
add('Predict Next UNLOCK','目标是同时预测16位计数器和附加滚动字段。后者是可观察的模2^16等差序列，并非需要破解的强密码。','解capture_c4.bin得到`AA AA D5 B8 4F 62 20 02 04 C1 8B 5A`等四帧；计数器0204至0207。||额外字段C18B、D4C2、E7F9、FB30每步差值模65536均为1337。||下一计数器0208；附加值`(FB30+1337)&FFFF=0E67`，必须保留前导0。||用大端字段拼成12字节完整帧。','原文记录 `flag{AAAAD5B84F622002080E675A}`。应以所有连续差分验证规律，且确认环绕截断。',pages='kn1cht合集 Keyfob / Predict Next UNLOCK')
add('Classic KeeLoq Garage - Find the Key','目标是由RF固定字段和安装备注恢复64位DeviceKey。备注直接给出Legacy派生式，不能将此题描述成攻击完整64位KeeLoq密钥空间。','Manchester解出`AA AA D5 | ENC32 | SERIAL32 | BTN8`；固定部分01D4A2B7 01，其中01对应OPEN。||读取memo_c5c6.txt：seed=6D3A91C4，`K=SEED || (SEED XOR SERIAL)`。||计算低32位6CEE3373，按高位seed、低位异或结果拼接。||用同一key解多个Hop作为交叉验证：其低16位计数器应连续，参见下一题。','原文记录 `flag{6D3A91C46CEE3373}`。输出16个大写HEX字符，不是seed本身。',pages='kn1cht合集 Classic KeeLoq Garage: Find the Key')
add('Classic KeeLoq Garage - Next HOP','目标是用已恢复的DeviceKey解密并递增Hop计数器，再重新加密生成下一OPEN帧。','使用key=6D3A91C46CEE3373及原文528轮KeeLoq，NLF=3A5C742E；保留32位数据宽度与64位key轮转索引。||四个Hop 913B00D7、0020D1FB、80ED145B、314C03E4解为ADC40040—ADC40043，说明只需递增低16位。||下一明文ADC40044加密得65317ADF；固定SERIAL=01D4A2B7、BTN=01保持不变。||拼接`AA AA D5 | 65317ADF | 01D4A2B7 | 01`。','原文记录 `flag{AAAAD565317ADF01D4A2B701}`。必须先验证解密历史Hop及加密回环，不对密文直接加1。',pages='kn1cht合集 Classic KeeLoq Garage: Next HOP')
add('Real KeeLoq Garage - Normal Learn','目标是从HCS301兼容固定字段及制造商代码派生DeviceKey。与Classic题不同，本题是Normal Learn，且34位固定部不可简单按整字节截断。','在434.040MHz提取250us Manchester chip；D5后为32位Hop与34位固定字段。||固定字段按`status(2)||button(4)||serial(28)`拆，得到status=00、button=1、serial=07A4C3D，与备注缺失的上位标签相符。||制造商key=89ABCDEF01234567。计算SourceH=60000000|serial=607A4C3D，SourceL=20000000|serial=207A4C3D，分别执行KeeLoq解密。||得到KeyH=BF61DA58、KeyL=FE545128；拼成64位DeviceKey。||用新key解四个观察Hop应得103D0040—103D0043，discrimination=03D应等于serial低10位。','原文记录 `flag{BF61DA58FE545128}`。连续计数与disc一致共同支持派生正确。',pages='kn1cht合集 Real KeeLoq Garage: Normal Learn')
add('Real KeeLoq Garage - Next HOP','目标是生成下次OPEN的逻辑帧。需要区分射频34bit固定字段和判题期待的32bit button+serial表示。','使用BF61DA58FE545128解四个Hop，得到103D0040至103D0043。||按`button(4)||status(2)||disc(10)||counter(16)`确认下一明文103D0044，再KeeLoq加密得2675F6FA。||逻辑固定部为`button=1 || serial=07A4C3D`，组成107A4C3D；不要对射频34bit右补零后输出041E930F4。||拼接前导同步AAAAD5、Hop与逻辑固定字段。','原文记录 `flag{AAAAD52675F6FA107A4C3D}`。这是逻辑帧字符串，不能直接当作完整空中发射bitstream。',pages='kn1cht合集 Real KeeLoq Garage: Next HOP')
(root/'sources/ai_rewrite_special_summary.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),'utf8')
print('written',len(data))
add('UART','目标是从Sigrok逻辑采样还原UART字节并解出flag。`.sr`本来就是ZIP容器，不应将ZIP结构本身误判为题目伪装。','解开会话文件读取metadata：1通道、采样率1MHz、unitsize=1、probe标为uart.ch1；定位logic-1-1原始采样。||统计最短稳定高/低脉宽，约8—9us，对应常用115200baud；采样率/9只是近似估计，不是精确波特率。||在UART解码器中设置rx=0、baudrate=115200，检查起始低电平、8位LSB-first数据、停止高电平；不要将采样字节直接当串口数据。||导出rx-data十六进制字节并转ASCII，查看完整内容。','原文结果 `0xfun{UART_82_M2_B392n9dn2}`。参考解码命令：`sigrok-cli -i logic-1-1 -I binary:numchannels=1:samplerate=1000000 -P uart:baudrate=115200:rx=0 -A uart=rx-data`。','原文用截图展示采样细节，正文已给关键参数；本次未运行Sigrok，不将其输出当现场验证。')
add('OutOfPhase','目标是从相位编码的OFDM类WAV中恢复消息。编码器oopenc定义了载波置换、QPSK旋转、分块顺序及差分相位；呼号是所有伪随机变换的种子。','从FANCY频域图案识别EP2AES，按base37→SplitMix64类混合→Speck类ARX生成器重建各域随机表。参数为8kHz、1440样点块、1280点FFT、160保护/重叠、256载波、6.25Hz间隔。||定位前导并校正约1—2Hz载波偏移。参考前导与采集FFT相位差对时间的斜率给出delta_f，用`exp(-2j*pi*delta_f*n/8000)`消除频偏。||对相邻块同载波做差分`S[t,k]/S[t-1,k]`；逆载波置换、QPSK旋转及4块顺序，将1024符号还原256字节。||校验RS(255,191)，GF多项式187、fcr=5、generator=2，并核对byte255的CRC8。只拼EP2AES的part0/3、1/3、2/3，原文对应burst9、14、17。||558字节拼接后逆domain2字节置换，再异或domain1密钥流；检查OOPH、u16长度、u32 CRC，最后读取message。','原文结果 `ASIS{R0t4t3dC4rri3rs_m1uAF0HBNhEJ4YJAUDQPhCNe2uk8vtY8mYVYg}`。层级校验应为前导→QPSK→RS/CRC8→OOPH及消息CRC。','本地writeup仅存README，文中decode_data.py等辅助脚本是否包含在附件需另核；不能把原文列出的脚本名视为本地已存在。不可混入EP2DES等其他呼号分片。')
add('Silent_Carrier','目标是联合USB配置抓包与DMR IQ信号恢复隐藏莫尔斯音频。关键是TYT Enhanced Privacy对49bit AMBE数据施加固定异或掩码，而非直接对PCM做AES解密。','筛选USB data_len=1032的传输并按顺序拼接片段，重建0xD0000字节codeplug。核对Radio ID1234、contact1、color1、slot1与RF一致。||从原始偏移59C0提取8组16字节key。CPS展示值为原始字节全反转，计算必须明确采用raw_radio_key。||IQ从2.4MHz移频-15500Hz、低通、50倍抽取得48kHz，再差分相位解4FSK；使用每符号10.00284采样点修正漂移，三段共594 bursts。||4级[-3,-1,+1,+3]映射dibit[3,2,0,1]，按DSD-FME表解交织，经mbelib纠错后才对49bit语音数据解密。掩码为AES-128-ECB(fixed_key,raw_radio_key)的高49bit，fixed_key=6e028d8acaeb9bbe4272fb82645631fa。||以已知静音帧FEA20202020800验证：第1段用K7，第2/3段用K8。FEC在隐私异或前，错误率不能判断key。||将AMBE经MD380模拟codec转8kHz音频，识别1kHz莫尔斯，点约80ms、划240ms、字母间600ms、单词间2.7s。','三段解出ASISN0 K3Y / N0 / V01C3，原文合成 `ASIS{N0_K3Y_N0_V01C3}`。关键证据是多组密文映射到相同静音帧，不依赖语音识别猜测。','本地README引用的direct_best.py及codec工具未在writeups目录中提供；复现还需相应实现。固定掩码不意味着真实DMR所有隐私模式都相同。')
add("D's Signpost",'目标是从五路混合RF信号恢复加密ZIP与密码。输入SigMF为cf32_le、500ksps、中心915MHz，关键信息分属+115kHz的APRS和+170kHz的DQPSK。','读取SigMF元数据并组复数IQ；FFT找到-180k、-70k、+45k、+115k、+170kHz。逐通道下变频、低通后再抽取，避免混叠。||-180kHz包络莫尔斯提示五路信号；+45kHz语音指向APRS密码，-70kHz提示比较前后符号相位。||+115kHz先FM解调，再Bell202 AFSK(1200/2200Hz，1200bps)，还原NRZI、定位HDLC7E、去bit stuffing并验证AX.25 FCS，得到密码dWt4Wxm6Xfn1ot02。||+170kHz在21.3—25.35秒按250baud采样，25kHz基带下每符号100样本。比较相邻符号相位，四峰0、±π/2、π支持DQPSK。||探索残余频偏、符号边界、4!位对映射与字节偏移；原文最终boundary=13、跳过26bit、MSB-first，定位PK0304与flag.txt。||以APRS密码解压ZIP，读取flag.txt。','原文结果 `FLAG{R4D10_FR3Q_L1TTL3_M4Z3}`。有效AX.25 CRC、ZIP结构及解压CRC共同支持结果。','最终solver依赖aprs_decode、clean_extract等未在本题writeups目录提供的模块，不能直接复制末尾代码就宣称可运行；正文给出算法片段，但仍需补齐辅助函数。','kn1cht合集 RF / D\'s Signpost')
add('Suspicious device 1','目标是从SD卡中的ARM iot-agent恢复通信协议，发现残留DEBUG_EXEC命令。入口不是题面给出的云地址，而是固件中的连接逻辑与provision.bin配置。','离线读取文件系统，检查/root/.ash_history与/usr/bin/iot-agent。原文以7-Zip探索镜像，并从配置/程序得出比赛云服务地址。||追踪send_command/build_packet，识别IOT1帧：magic4、version1=01、command1=7F、flags/reserved各1、device_id16、length4、payload、CRC32。||构造JSON payload的token及cmd字段；示例device_id为dev-7f3a91c2补NUL，debug token为dbg-9b7c4a1e-prod-only。CRC覆盖header+payload，length仅计payload。||只在重建的比赛环境测试DEBUG_EXEC，通过服务器响应确认执行位置，再读取根目录flag_stage1.txt。','官方第93页展示成功返回flag_stage1.txt；本文不从低清截图猜录整串flag。应保存返回帧、状态和输出作验证。','整数大小端须从build_packet汇编确认，幻灯片表格未完整规定；单靠该表不能声称完整可运行。远程地址为历史赛事端点，本次未连接。','官方PDF第89—93页')
add('Suspicious device 2','目标是利用上一题已有的命令执行能力，找到内部数据库中的第二阶段flag。需要先读拓扑与现成查询工具，不能假设公网可以直接访问DB。','复用stage1的DEBUG_EXEC通道，查看/app/config/cloud-topology.json；官方配置指向iot-db:5432、数据库iot_cloud，同时存在SSH22。||检查/app/tools/query_db.py及连接配置，确认通过环境变量QUERY传入查询字符串。||先列information_schema.tables确定schema和flag表，避免把telemetry或maintenance_users误当flag来源。||通过现成脚本执行`SELECT * FROM flag`并保存响应；查询在云容器内执行，因此能到达内部iot-db。','官方第96页给出flag表返回记录。成功标准是从目标DB的flag表读取值，不是只枚举出表名。','依赖stage1环境和服务状态；凭据、库名及工具路径均属于题目镜像。本次没有执行远程命令或数据库查询。','官方PDF第94—96页')
add('Suspicious device 3','目标是在内部DB主机读取受flagreader组保护的stage3文件。链路为数据库泄露维护账户→内部SSH→SGID工具的TOCTOU，权限提升目标是组读取能力。','从maintenance_users找到dbmaint账户，借stage1云端命令通道连接iot-db SSH；官方示例密码Maint@2026!属于赛事环境。||检查/home/flagreader/flag_stage3.txt权限及/usr/local/bin/db_diag_report，后者带flagreader SGID。||逆向工具：路径必须位于/tmp/dbdiag/；lstat拒绝符号链接并要求文件owner等于真实UID；之后usleep(200000)，再按原路径open读取。||在受控复现里先提供自己拥有的普通文件通过检查，在200ms窗口将同一路径替换为指向flag的符号链接。open跟随新目标，程序仍具有flagreader有效组。||读取stdout并保留成功证据；失败时区分路径前缀、owner和竞争时序，不能把普通dbmaint权限说成root。','验证需看到stage3文件内容，而不是仅看到SSH登录或SGID位。漏洞根因是检查的文件与使用的文件未绑定到同一个已打开描述符。','官方第101页提供反编译逻辑，本地不含独立完整竞争脚本；本文仅静态整理，没有进行跨主机连接。','官方PDF第97—101页')
add('Tiny crackme','目标是恢复FLAG{30字符}输入。CTF任务的ECC相关哈希看似很强，但UART任务在每5字符处检查CRC32，泄露6个短块的约束，提供更小的搜索空间。','从FreeRTOS任务创建点识别uart与ctf两个任务，沿UART调用链13270→10418→1128→5B7C→5A50→121A4定位CRC。||实现反射CRC32，多项式EDB88320、初始FFFFFFFF、最终按位取反。六个目标是80B0CEE1、71F28109、F38B1F2F、FB2059C6、334BD5E1、8DD5DB45。||在字母数字下划线字符集上建立4字节前向CRC状态表；枚举第5字节，从目标内部状态反推一步，与前向表匹配。||每块保留所有候选并正向验CRC，再拼30字符；CRC有碰撞，最终还应经过完整ctf任务验证。','原文6块为L0W_L、4Y3R_、SK1LL、S_M4Y、_H3LP、S_Y0U，合成 `FLAG{L0W_L4Y3R_SK1LLS_M4Y_H3LPS_Y0U}`。','原文dict只保留每个CRC状态的一个4字节候选，可能覆盖碰撞；若复现失败需保留候选列表。63^4约1575万条Python记录，内存不可忽略。本次未执行穷举或QEMU。')
add('23_虚验室制取稀硫酸','目标仅限题目软PLC仿真：让真实模拟反应釜温度>90、液位>100，同时SIEM不报警，flag出现在TUI公告板。直接篡改过程显示值不能满足物理过程判定。','先读快照、变量类型和ZMQ命令端点，对应controller、panel、vessel及传感器；分清tui观察、ctf脚本与upload上传三种账号。||按原文pwn_natural的顺序先提高MAX_SAFE_*等阈值，再启动心跳、CMD_Start和搅拌；阈值修改必须发生在工艺变化前。||保持仿真酸输入、限制水/冷却与产品流出，让模拟物理状态自然演进；脚本持续维护latch和heartbeat，不以force写Vessel_Temp/Level作为主方法。||并行观察tui，直到温度/液位阈值及SIEM/latch条件同时满足，再读取公告板。','原文赛事记录 `NepCTF{d5ed8d22-0bc2-0e1e-d663-0614446cb241}`，实例可能动态换flag。验证必须同时保留实际过程值、告警状态与公告板输出。','这是仿真题流程；原文脚本硬编码历史HOST、PORT及本地目录，需要替换为受控实例配置。本文未操作PLC或执行脚本。')
add('24_赛博心情电梯','目标仅限CEIBA软PLC电梯仿真：在门实际开启时完成跨层运动并满足题目判定。关键是形成真实行程后再影响门联锁，单独伪造关门位不会让READY状态的轿厢移动。','正常操作先到高楼层（原文为5层），呼叫低层形成DOWN行程，观察motion而非只看目标楼层。||按原文live_travel_then_spoof.py连接ZMQ状态与命令，保持实际门开启窗口中的bDoorFullyClosed、驱动使能和电机方向伪造与行程时序一致。||并行TUI持续OPEN与呼1层，使真实OPEN与UP/DOWN跨层状态发生重叠；不能只修改单个界面变量。||记录起止楼层、门开百分比、运动状态及公告板，一次失败应先判断是否已形成真实行程。','原文赛事flag为`NepCTF{9f323c33-47a4-6565-9e81-7e4e8a9500dc}`，另一次实例flag不同。成功依据是跨层与门开重叠后公告板结果。','原文含多版测试/race脚本，主线是live_travel_then_spoof，不能把早期失败试验当最终流程。本次未执行仿真控制。')
add('37_UnknownFirmware','目标是把Telink/KNLT固件中的显示缓冲恢复为二维码。已有solver是启发式位图扫描，而非完整Telink指令集反编译。','查找KNLT/TLNK魔数以确认容器特征；记录位置，但不要把魔数附近任意字节都视为图像。||按原solver候选偏移0、192、256、512、1024取数据，以np.unpackbits生成MSB-first位序；反色为黑白图。||枚举宽40—299与候选高w、90、122、128、250、min(h,200)，每次只取w*h位；注释提示曾命中skip192_41x90。||对图像执行二维码解码，保存命中偏移、尺寸及原始payload，确保可重复解出同一内容。','原文记录 `NepCTF{U_Have_Dec0mpiled_Telink_FirmWareWooooW}`。二维码结构和解码结果是验证点，文件含KNLT并不能直接证明成功。','代码存在筛选风险：先按整个blob计算h并要求h<=400，较大固件可能在尝试局部hh之前就全部跳过。复现需按明确窗口切片并检查边界；原文仅给启发式而非保证解。')
add('46_谁引闪了我的灯','目标是根据ESP32/Godox引闪协议信息组16字节帧，再对指定十六进制文本做MD5。必须区分原始字节与HEX字符串、以及大小写。','从配图comment取得channel/id线索；原文ch18/id19对应group=1、id=0x13、type=1、payload起始01。||构造前15字节：55 01 13 01 01加10个00；校验和为前15字节求和模256=6B，附加后长度16。||按题意确认MD5输入是连续HEX文本，而不是16字节原始帧；原文脚本分别打印大写与小写两种候选。||独立常量核算表明：大写HEX文本的MD5=5bf7d6ca3d718c33301a52e5f45909b8，小写HEX文本的MD5=b3e11594a5e73662cd805eb31e6447ba；原文声明的flag对应大写。','原文宣称 `NepCTF{5bf7d6ca3d718c33301a52e5f45909b8}`。本次只重新计算已知16字节常量的MD5，确认它来自大写HEX文本；未执行题目solver。原注释lowercase应修正为uppercase。','channel→group的推导在正文略写；需要原题协议定义支持。该文有“去空格”与大小写不一致问题，本次未运行solver，仅做已知常量的MD5核算。')
add('SU_EzRouter','现有材料只有exp.py。它的静态行为是先借auth参数取得session，再安排WiFi/黑名单状态，最后提交含amd64 shellcode的VPN配置；漏洞根因需要结合CGI二进制进一步确认。','阅读login_bypass：请求`/www/http?action=login&auth=1`，代码把cookie中存在session_id当登录成功条件，后续复现还应验证实际权限。||调用wifi.cgi保存短ssid/password，再通过list.cgi添加7条black条目；这说明利用对状态/内存布局有前置依赖，不能删掉。||set_vpn向vpn.cgi提交JSON，pass为0x19个字符，cert字节为00 e9 f2 00 00 00，custom为shellcode填充到0x7eb后补NUL。custom字节被B64:前缀编码，其他bytes转\\xNN文本。||shellcode旨在把题目flag写入./www/flag.html。检查服务端对字段的解码、内存拷贝和控制流后，才能判断跳转字节与落点。','脚本没有flag输出或成功日志，edit_vpn和apply_vpn整个触发段被三引号注释。只能确认“作者构造的利用输入”，不能宣布完整利用链已运行成功。','不应臆造具体堆漏洞名、覆盖偏移或已取得shell。当前缺口：CGI根因、最终触发条件、输出读取与成功验证。依赖requests和pwntools，且context.arch=amd64。')
add('SU_老年固件','现有writeup是分层固件提取分析记录，不是完整flag解答。可确认old.bin经单字节XOR7F后包含U-Boot风格头、XZ流与SMALLFW容器。','从attachment.zip取attachment/old.bin，逐字节异或0x7F，核对UBHDRv1、U-Boot1.1.3、Board:malta及baudrate=115200等字符串。||在解码结果中定位XZ魔数FD377A585A00，原文顶层偏移2028、50ED4、51AA4。使用LZMADecompressor检查eof/unused_data，避免把多个流误当一个。||后两个流展开为SMALLFW，进一步搜索内层XZ并解出ZIP；按ZIP条目读file_0_0.txt等样本文件。||记录各层偏移、长度、文件名和校验，不因看到glibc字符串就宣称恢复出了程序源码树。','原文没有flag或判题成功证据。已完成部分仅是恢复容器与CTF_PAYLOAD样本文本；必须在后续找到真实题目校验逻辑才能补成完整解答。','提取脚本默认attachment路径相对writeups层级可能不匹配，应显式传--attachment。ZIP成员写盘前还须规范化路径并限制在输出目录。本文没有运行原提取脚本。')
add('Brick_by_Brick','目标是把时间戳/逻辑电平CSV解为UART，再从伪Linux启动日志取HEX编码flag。核心参数约30us/bit、33333baud、8N1、LSB-first。','读取timestamp与logic_level，统计相邻采样间隔及高低run长度。约30/60/90us的倍数提示位周期，但需用多帧起止位验证。||从空闲高到低的start边沿，以1.5T、2.5T直到8.5T取8个数据bit，用sum(bit<<位置)还原字节；9.5T应为高停止位。||输出ASCII日志，定位secretflag:后的554d4153537b553452375f31355f3768335f623335372c5f72316768373f7d，再HEX解码。','原文结果 `UMASS{U4R7_15_7h3_b357,_r1gh7?}`。应核对UART停止位、可读日志和HEX转码三个层次。','原文run持续时间实现用timestamps[j-1]-timestamps[i]，会少一个采样间隔；不要原样照抄。按半开区间边界计算，或直接使用时间轴中心采样。')
add('Smart_Brick_v2','目标是从KiCad PCB网表模拟组合逻辑。7个输入位、19个LED，每个LED仅对一个ASCII值亮起，按D1—D19的触发字符拼flag。','使用S-expression/括号匹配解析footprint及pad/net，不用单行正则解析嵌套多行pad。提取器件型号、脚号到net映射。||依据74LS04/21/27/08/32/86/00/02/20的实际引脚定义建立布尔门图，再追踪每个2N7002 gate对应LED输出。||按IN0为最低位枚举0—127，拓扑求值全部门；常量电源、悬空端和输出极性要明确。||为每个D编号收集使其亮起的所有输入值，应各有唯一候选；相同字符可对应多个LED，不能去重后拼接。','原文D1—D19依次得到 `UMASS{In_Th3_G4t3s}`。验证19个输出各有唯一解且同一字符重复位置保留。','原文把NAND(NAND(G7,x),NAND(G7,NOT x))称为XOR并不准确，该式化简为G7。依据真值表模拟即可避免此误导；本地README引用的完整模拟脚本未在writeups中提供。')
